+ * Legge i byte disponibili nel registro RBR e li scrive nel buffer corrente.
+ *
+ * @param id  indice della periferica CE
+ */
+extern "C" void c_driver_ce(natl id)
+{
+    if (id >= next_ce)
+        return;
+
+    des_ce *ce = &array_ce[id];
+
+    // Il driver gestisce le interruzioni solo se è in corso un'operazione
+    if (!ce->enabled)
+        return;
+
+    // Legge il prossimo byte disponibile
+    if (ce->quanti > 0) {
