+        *(ce->buf++) = inputb(ce->iRBR);
+
+        // Se tutti i byte sono stati letti, segnala il completamento
+        if (ce->quanti == 0) {
+            // Incrementa il contatore del semaforo di sincronizzazione
+            ce->sync--;
+            if (ce->sync >= 0)
+                // C'è un processo pronto, risvegliarlo
+                inserimento_lista(array_dess[ce->sync].pointer, esecuzione);
+        }
+    }
+}
 //   SOLUZIONE 2024-01-10 )

+/**
+ * @brief Legge n byte da una periferica CE con timeout.
+ *
+ * @param id       indice della periferica CE
+ * @param buf      puntatore al buffer dove scrivere i byte letti
+ * @param quanti   riferimento al numero di byte da leggere (usato come output per i byte effettivamente letti)
+ * @param to       timeout per l'operazione
+ * @return         true se l'operazione è completata entro il timeout, false altrimenti
+ */
+extern "C" bool ceread_n_to(natl id, char *buf, natq& quanti, natl to)
+{
+    // Controlli pre-acquisizione del mutex
+    if (id >= next_ce) {
+        flog(LOG_WARN, "ceread_n_to: id dispositivo non valido: %u", id);
+        abort_p();
+        return false;
+    }
+
+    if (!buf) {
+        flog(LOG_WARN, "ceread_n_to: buffer nullo");
+        abort_p();
+        return false;
+    }
+
+    // Acquisizione del mutex per accedere alla periferica
+    c_sem_wait(array_ce[id].mutex);
+
+    des_ce *ce = &array_ce[id];
+
+    // Controlli post-acquisizione del mutex
+    // Verifica che il puntatore al buffer sia scrivibile (non const)
+    if (buf) {
+        // Verifica semplice: il puntatore non deve essere const
+        // (questo è un controllo runtime in un sistema simulato)
+        if ((uintptr_t)buf & 0x80000000) {
+            flog(LOG_WARN, "ceread_n_to: buffer non scrivibile");
+            c_sem_signal(ce->mutex);
+            abort_p();
+            return false;
+        }
+    }
+
+    if (!to) {
+        flog(LOG_WARN, "ceread_n_to: timeout nullo");
+        c_sem_signal(ce->mutex);
+        abort_p();
+        return false;
+    }
+
+    // Controllo Cavallo di Troia: il dispositivo non deve essere già in uso
+    if (ce->enabled) {
+        flog(LOG_WARN, "ceread_n_to: dispositivo occupato (Cavallo di Troia)");
+        c_sem_signal(ce->mutex);
+        abort_p();
+        return false;
+    }
+
+    // Inizializzazione del dispositivo
+    ce->enabled = true;
+    ce->buf = buf;
+    ce->quanti = quanti;
+
+    // Aspetta il completamento del trasferimento con timeout
+    c_sem_wait_to(ce->sync, to);
+
+    // Rilascia il mutex
+    c_sem_signal(ce->mutex);
+
+    return true;
+}
+
 // ( ESAME 2024-01-10


